// Package settings provides configuration loading for Entire.
// This package is separate from cli to allow strategy package to import it
// without creating an import cycle (cli imports strategy).
package settings

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/redact"
)

const (
	// EntireSettingsFile is the path to the Entire settings file
	EntireSettingsFile = ".entire/settings.json"
	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
	EntireSettingsLocalFile = ".entire/settings.local.json"
	// ClonePreferencesFile is the path inside the git common dir for clone-local preferences.
	ClonePreferencesFile = "entire/preferences.json"
)

type worktreeRootContextKey struct{}

// WithWorktreeRoot returns a context that makes settings.Load resolve project
// and clone-local settings relative to worktreeRoot instead of the process cwd.
func WithWorktreeRoot(ctx context.Context, worktreeRoot string) context.Context {
	if worktreeRoot == "" {
		return ctx
	}
	return context.WithValue(ctx, worktreeRootContextKey{}, filepath.Clean(worktreeRoot))
}

func worktreeRootFromContext(ctx context.Context) (string, bool) {
	root, ok := ctx.Value(worktreeRootContextKey{}).(string)
	return root, ok && root != ""
}

// Commit linking mode constants.
const (
	// CommitLinkingAlways auto-links commits to sessions without prompting.
	CommitLinkingAlways = "always"
	// CommitLinkingPrompt prompts the user on each commit (default for existing users).
	CommitLinkingPrompt = "prompt"
)

// EntireSettings represents the .entire/settings.json configuration
type EntireSettings struct {
	// Enabled indicates whether Entire is active. When false, CLI commands
	// show a disabled message and hooks exit silently. Defaults to true.
	Enabled bool `json:"enabled"`

	// LocalDev indicates whether to use "go run" instead of the "entire" binary
	// This is used for development when the binary is not installed
	LocalDev bool `json:"local_dev,omitempty"`

	// LogLevel sets the logging verbosity (debug, info, warn, error).
	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
	// Defaults to "info".
	LogLevel string `json:"log_level,omitempty"`

	// StrategyOptions contains strategy-specific configuration
	StrategyOptions map[string]any `json:"strategy_options,omitempty"`

	// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
	// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
	// that don't source shell profiles and can't find "entire" on PATH.
	AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`

	// Telemetry controls anonymous usage analytics.
	// nil = not asked yet (show prompt), true = opted in, false = opted out
	Telemetry *bool `json:"telemetry,omitempty"`

	// Redaction configures PII redaction behavior for transcripts and metadata.
	Redaction *RedactionSettings `json:"redaction,omitempty"`

	// ReviewProfiles maps profile names (e.g. "general", "security") to
	// named review setups. `entire review` runs one profile: its canonical task
	// is fanned out to the configured agents, then an optional master agent
	// consolidates the worker reports.
	ReviewProfiles map[string]ReviewProfileConfig `json:"review_profiles,omitempty"`

	// ReviewDefaultProfile is the profile used by `entire review` when no
	// profile is supplied. If empty, `general` is used when present, otherwise
	// the single configured profile is used.
	ReviewDefaultProfile string `json:"review_default_profile,omitempty"`

	// Deprecated: legacy pre-profile review settings. Kept so old config files
	// still parse. `entire review` reads this only as a compatibility fallback
	// when no review_profiles are configured, exposing it as the general profile.
	Review map[string]ReviewConfig `json:"review,omitempty"`

	// ReviewFixAgent is a legacy saved fix-agent preference. The `entire review
	// --fix` flow has been removed; this field is retained only so older
	// settings/preferences files still parse. It is no longer read by
	// `entire review`.
	ReviewFixAgent string `json:"review_fix_agent,omitempty"`

	// Investigate holds configuration for `entire investigate`. Empty means
	// `entire investigate` triggers the first-run picker.
	Investigate *InvestigateConfig `json:"investigate,omitempty"`

	// CommitLinking controls how commits are linked to agent sessions.
	// "always" = auto-link without prompting, "prompt" = ask on each commit.
	// Defaults to "prompt" (preserves existing user behavior).

package cli

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/checkpointpolicy"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/telemetry"
	"github.com/entireio/cli/cmd/entire/cli/versioncheck"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/perf"

	"github.com/spf13/cobra"
)

// gitHooksDisabled is set by PersistentPreRunE when Entire is not set up or disabled.
// When true, all git hook commands return early without doing any work.
var gitHooksDisabled bool

// gitHookContext holds common state for git hook logging.
type gitHookContext struct {
	hookName string
	ctx      context.Context
	span     *perf.Span
	strategy *strategy.ManualCommitStrategy
}

// newGitHookContext creates a new git hook context with logging and a root perf span.
// The perf span ensures all perf.Start calls in strategy methods become child spans,
// producing a single perf log line per hook with a full timing breakdown.
// Callers must defer g.span.End() to emit the perf log.
func newGitHookContext(ctx context.Context, hookName string) *gitHookContext {
	ctx = logging.WithComponent(ctx, "hooks")
	ctx, span := perf.Start(ctx, hookName,
		slog.String("hook_type", "git"))
	g := &gitHookContext{
		hookName: hookName,
		ctx:      ctx,
		span:     span,
	}
	g.strategy = GetStrategy(ctx)
	return g
}

// logInvoked logs that the hook was invoked.
func (g *gitHookContext) logInvoked(extraAttrs ...any) {
	attrs := []any{
		slog.String("hook", g.hookName),
		slog.String("hook_type", "git"),
		slog.String("strategy", strategy.StrategyNameManualCommit),
	}
	logging.Debug(g.ctx, g.hookName+" hook invoked", append(attrs, extraAttrs...)...)
}

// logCompleted records the error on the perf span.
func (g *gitHookContext) logCompleted(err error) {
	g.span.RecordError(err)
}

func (g *gitHookContext) skipUnsupportedCheckpointPolicy() bool {
	// Callers return success when this is true because policy failures should
	// disable Entire checkpoint work, not make Git reject the user's operation.
	repo, err := gitrepo.OpenCurrent(g.ctx)
	if err != nil {
		return g.skipUnreadableCheckpointPolicy(err)
	}
	defer repo.Close()

	state, err := checkpointpolicy.ReadLocal(g.ctx, repo)
	if err != nil {
		return g.skipUnreadableCheckpointPolicy(err)
	}

	policy := state.Policy
	if checkpointpolicy.CanSatisfyPolicy(policy) {
		return false
	}

	logging.Warn(g.ctx, "checkpoint policy unsupported; skipping git hook",
		slog.String("checkpoint_version", policy.CheckpointVersion),
		slog.String("checkpoint_min_version", policy.CheckpointMinVersion))
	if interactive.CanPromptInteractively() {
		fmt.Fprint(os.Stderr, checkpointpolicy.UnsupportedPolicyMessage(
			policy,
			versioncheck.UpdateCommandForCurrentBinary(versioninfo.Version),
		))
	}
	emitCheckpointPolicyBlocked(g.ctx, telemetry.CheckpointPolicyBlockedEvent{
		Hook:                 g.hookName,
		HookType:             telemetry.PolicyBlockedHookTypeGit,
		Reason:               telemetry.PolicyBlockedReasonUnsupported,
		Outcome:              telemetry.PolicyBlockedOutcomeSkipped,
		CheckpointVersion:    policy.CheckpointVersion,
		CheckpointMinVersion: policy.CheckpointMinVersion,
	})
	return true
}

// skipUnreadableCheckpointPolicy warns, notifies the user, and reports the
// policy-blocked telemetry event for a hook whose checkpoint policy could not be
// read. It always returns true so callers skip Entire checkpoint work.
func (g *gitHookContext) skipUnreadableCheckpointPolicy(err error) bool {
	logging.Warn(g.ctx, "checkpoint policy read failed; skipping git hook",
		slog.String("error", err.Error()))
	if interactive.CanPromptInteractively() {
		fmt.Fprintf(os.Stderr, "[entire] Could not read checkpoint policy; skipping Entire checkpoint work: %v\n", err)
	}
	emitCheckpointPolicyBlocked(g.ctx, telemetry.CheckpointPolicyBlockedEvent{
		Hook:     g.hookName,
		HookType: telemetry.PolicyBlockedHookTypeGit,
		Reason:   telemetry.PolicyBlockedReasonUnreadable,
		Outcome:  telemetry.PolicyBlockedOutcomeSkipped,
	})
	return true
}

// initHookLogging initializes logging for hooks by finding the most recent session.
// Returns a cleanup function that should be deferred.
// If Entire is not active for this repo (repo-level setup or the user-global
// tier), returns a no-op to avoid creating files.
func initHookLogging(ctx context.Context) func() {
	// Don't create any files if Entire is not active for this repo
	// (repo-level setup or the user-global tier). This is checked here as
	// defense-in-depth (also checked in PersistentPreRunE); both layers of
	// the gate must use the same predicate, settings.IsActiveForRepo, so
	// global-mode repos get hook logging and redaction configuration too.
	if !settings.IsActiveForRepo(ctx) {
		return func() {}
	}

	// Set up log level getter so logging can read from settings
	logging.SetLogLevelGetter(GetLogLevel)

	// Read session ID for the slog attribute (empty string is fine - log file is fixed)
	sessionID := strategy.FindMostRecentSession(ctx)
	if err := logging.Init(ctx, sessionID); err != nil {
		// Init failed - logging will use stderr fallback
		return func() {}
	}

	// Configure redaction once at startup: PII (opt-in), inline custom_redactions,
	// and rule packs discovered under .entire/redactors/. No-op if nothing is configured.
	strategy.EnsureRedactionConfigured()

	return logging.Close
}

// hookLogCleanup stores the cleanup function for hook logging.
// Set by PersistentPreRunE, called by PersistentPostRunE.
var hookLogCleanup func()

func newHooksGitCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:    "git",
		Short:  "Git hook handlers",
		Long:   "Commands called by git hooks. These delegate to the current strategy.",
		Hidden: true, // Internal command, not for direct user use
		PersistentPreRunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			// Check if Entire is active for this repo before doing any work.
			// This prevents global git hooks from doing anything in repos
			// where Entire was never enabled (repo-level or via the
			// user-global tier) or has been disabled.
			if !settings.IsActiveForRepo(ctx) {
				gitHooksDisabled = true
				return nil
			}
			// Discover external agent plugins so GetByAgentType works correctly
			// during condensation (e.g. post-commit). Without this, external agents
			// registered in the hook phase cannot be resolved here, causing token
			// usage and other agent-specific data to be missing from metadata.json.
			discoveryCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
			defer cancel()
			external.DiscoverAndRegister(discoveryCtx)
			hookLogCleanup = initHookLogging(ctx)
			return nil
		},
		PersistentPostRunE: func(_ *cobra.Command, _ []string) error {
			if hookLogCleanup != nil {
				hookLogCleanup()
			}
			return nil
		},
	}

	cmd.AddCommand(newHooksGitPrepareCommitMsgCmd())
	cmd.AddCommand(newHooksGitCommitMsgCmd())
	cmd.AddCommand(newHooksGitPostCommitCmd())
	cmd.AddCommand(newHooksGitPostRewriteCmd())
	cmd.AddCommand(newHooksGitPrePushCmd())

	return cmd
}

func newHooksGitPrepareCommitMsgCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "prepare-commit-msg <commit-msg-file> [source]",
		Short: "Handle prepare-commit-msg git hook",
		Args:  cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if gitHooksDisabled {
				return nil
			}

			commitMsgFile := args[0]
			var source string
			if len(args) > 1 {
				source = args[1]
			}

			g := newGitHookContext(cmd.Context(), "prepare-commit-msg")

